window.kbPageData["views/entry/k-a68bda1c4f2cde51"] = {"key":"entry/k-a68bda1c4f2cde51","state":{"route":"entry/k-a68bda1c4f2cde51"},"node":{"id":"k-a68bda1c4f2cde51","mode":"k","title":"高质量与高规格","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["“高质量”与“高规格”的语义和搭配","高质量与高规格的词义侧重及其与“建设”的搭配"],"qs":["江苏 2024 B类 行测#35","江苏 2024 C类 行测#39"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":1,"directorySummary":"高质量侧重工作过程或成果的质量较高。高规格侧重规格、标准或层级较高。","review":{"definition":"高质量侧重工作过程或成果的质量较高。高规格侧重规格、标准或层级较高。","explanation":"第35题第三空放在“建设国家植物园体系”之前。“高质量建设”强调把体系建好，与后文构建全国植物迁地保护网络的任务相衔接。“高规格”会把注意力引向植物园体系的规格或层级，材料未提出提高规格或层级的要求。","references":[],"evidence":"“高质量”侧重强调产品或工作更优","disposition":"独立词条","basis":"据原题和解析编释。","title":"高质量与高规格","related":[],"examFocus":{"江苏 2024 B类 行测#35":"第三空修饰“建设”，要结合后文的任务，辨析“高质量”和“高规格”各自评价的是建设的哪个方面。"}},"readings":[{"origin":"k-a68bda1c4f2cde51","title":"高质量与高规格","qs":["江苏 2024 B类 行测#35"],"definition":"高质量侧重工作过程或成果的质量较高。高规格侧重规格、标准或层级较高。","explanation":"第35题第三空放在“建设国家植物园体系”之前。“高质量建设”强调把体系建好，与后文构建全国植物迁地保护网络的任务相衔接。“高规格”会把注意力引向植物园体系的规格或层级，材料未提出提高规格或层级的要求。","evidence":"“高质量”侧重强调产品或工作更优","doubt":"","references":[]},{"origin":"k-df5320bfab55b91e","title":"高质量与高规格","qs":["江苏 2024 C类 行测#39"],"definition":"“高质量”强调事物的品质或工作的完成水平高，“高规格”强调规模、配置、礼仪等方面的规格高。","explanation":"第三空位于“建设国家植物园体系”之前。“高质量建设”评价的是建设工作的水平，符合通过建设植物园体系和迁地保护网络来加强植物保护的语意。若要用“高规格”描述所建体系，写成“建设高规格的国家植物园体系”更清楚，但题干没有交代该体系的规模或配置规格。因此在前两空保留的A、C两项中，第三空支持C项。","evidence":"“高质量”侧重强调产品或工作更优","doubt":"","references":[]}]},"questions":{"江苏 2024 B类 行测#35":{"paper":"江苏 2024 B类 行测","n":35,"mod":"言语理解与表达","src":["0ae7ac475476e5635bd7.pdf",6],"asrc":["8dd171daee6fc74e9718.pdf",12],"card":"3808d0ae23a07124d310494a","links":[{"id":"k-a68bda1c4f2cde51","role":"直接考查","why":"“高质量”可修饰建设过程并强调把工作做得更好，“高规格”侧重标准或规格层级。"}]},"江苏 2024 C类 行测#39":{"paper":"江苏 2024 C类 行测","n":39,"mod":"言语理解与表达","src":["3f1ec77ae8a18519b57e.pdf",7],"asrc":["02d6b49839583bdaf297.pdf",12],"card":"fe3ba65478c15912dbba8a79","links":[{"id":"k-a68bda1c4f2cde51","role":"直接考查","why":"第三空修饰建设行为，需要区分建设质量与所建对象的规格。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-a68bda1c4f2cde51":[["江苏 2024 B类 行测#35","江苏 2024 C类 行测#39"]]}};
